import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { Field, runtimeSchema } from '../src/config/runtime-schema';

export function configurationArtifacts(): Record<string, string> {
  const example = [
    '# Generated by npm run config:generate; do not edit by hand.',
    '# Development defaults only. Uncomment and supply required settings for deployment.',
    '# Empty assignments are rejected. Use exactly one name per alias group.',
    '',
  ];
  const docs = [
    '# Runtime configuration reference',
    '',
    'Generated from `src/config/runtime-schema.ts`; run `npm run config:generate`.',
    '',
    'Staging/production require explicitly supplied deployment settings. All supplied values are validated; empty values and simultaneous aliases are errors. Runtime values are snapshotted once before Nest bootstrap. Restart after configuration changes.',
    '',
    'A release file must match `CONTRACT_RELEASE_SHA256`, `CONTRACT_RELEASE_ID`, `CHAIN_ID` and `CONTRACT_RELEASE_DEPLOYMENT_BLOCK`. This boundary pins metadata; the prerequisite canonical-manifest validator owns ABI/event/freshness and network verification.',
    '',
    'Legacy `RELEASE_MANIFEST_MAX_AGE_MS` must migrate to `CONTRACT_RELEASE_MAX_AGE_DAYS`; downstream milliseconds are derived. Same-key file precedence is process environment > `.env.local` > `.env`; duplicate assignments inside either file are rejected.',
    '',
    '| Variable | Type | Default | Required explicitly when deployed | Aliases (use only one) |',
    '| --- | --- | --- | --- | --- |',
  ];
  for (const [key, definition] of Object.entries(runtimeSchema)) {
    const field: Field<unknown> = definition;
    example.push(
      `# ${field.description}${field.productionRequired ? '; required explicitly in staging/production' : ''}`,
    );
    if (field.aliases?.length)
      example.push(`# Aliases: ${field.aliases.join(', ')} (choose only one)`);
    // Required deployed settings must remain obvious, even when a dev default exists.
    example.push(
      field.default === undefined ? `# ${key}=` : `${key}=${field.default}`,
      '',
    );
    docs.push(
      `| ${key} | ${field.description.replaceAll('|', '/')} | ${field.default ?? '(unset)'} | ${field.productionRequired ? 'yes' : 'no'} | ${field.aliases?.join(', ') ?? '-'} |`,
    );
  }
  return {
    '.env.example': example.join('\n'),
    'docs/RUNTIME_CONFIGURATION.md': docs.join('\n') + '\n',
  };
}

if (require.main === module) {
  for (const [file, content] of Object.entries(configurationArtifacts())) {
    const path = resolve(__dirname, '..', file);
    if (process.argv.includes('--check')) {
      if (readFileSync(path, 'utf8').replaceAll('\r\n', '\n') !== content)
        throw new Error(`Configuration documentation drift: ${file}`);
    } else writeFileSync(path, content);
  }
}
